-- Polestar.Codex: every item, mount, pet, NPC, quest, zone and dungeon with
-- where it comes from, read from the load-on-demand data addon
-- Polestar_Codex (generated by `node tools/polestar.js codex build`, format
-- in tools/lib/codex/pack.js). The pack calls Register per chunk of a group
-- with two long strings (names and compact records, one line per entry) and
-- RegisterIndex once per searchable kind. Nothing is parsed at load or
-- indexed afterwards: an entry is one plain find of "\n" .. id .. "\t" in its
-- chunk (tens of microseconds), and a record is decoded on first access
-- (cached weakly). Contract: docs/ARCHITECTURE.md, "Lookup".
--
--   Codex.Load() -> loaded, reason   -- Data.Pack("Polestar_Codex"); fires CODEX_LOADED(meta) once
--   Codex.IsLoaded() ; Codex.Meta()
--   Codex.Item(id) / Npc(id) / Object(id) / Quest(id) / Instance(key) / Zone(id) / Faction(id)
--   Codex.Spell(spellId) -> { id, kind, item, name, class } | nil
--   Codex.Name(kind, id) -> name | nil   -- no decoding; "item" spans every item kind,
--                                           "npc" npc + rare, "object" object + treasure
--   Codex.Index(kind) -> blob | nil      -- the search index of a kind (item mount pet recipe
--       tabard npc rare quest zone instance treasure), never loads the pack; lines
--       "\2" .. folded .. "\1" .. id .. "," .. quality .. "," .. status .. "," .. #name .. "\n"
--       (folded = Search.Fold(name) without its leading space; status r|n|'')
--   Codex.WithRole(role) -> { npcId, ... } sorted (role as in npc.roles: "vendor",
--       "trainer:164" profession trainers by skillLine, "class:MAGE" class trainers)
--   Codex.Loot(kind, id) -> { itemId, ... }   -- kind "rare" | "npc" (npc + rare) | "treasure" |
--       "object" (object + treasure); what rares and treasures drop, best-known first
--       (capped); empty table when unknown
--   Codex.Each(kind, fn(id, name, quality, status))  -- kinds: item mount pet recipe tabard npc rare
--       quest zone instance treasure object faction spell; quality and status (item.status:
--       "retired" | "nosource" | nil) only for item kinds;
--       fn returning false stops the walk. "item" is plain items only (no overlap).
--   Codex.Register(group, names, records, lo, hi) ; Codex.RegisterIndex(kind, blob)   -- pack files only
--
-- Records use the codex JSON field names (data/forever/codex/*.json), with
-- 1-based arrays; JSON nulls are absent.

local ADDON, ns = ...

local Codex = {}
ns.Codex = Codex

local PACK = "Polestar_Codex"

local type, tonumber, pairs = type, tonumber, pairs
local char, byte, sub, find, gsub, gmatch = string.char, string.byte, string.sub, string.find, string.gsub, string.gmatch

-- group -> { chunk, ... }; chunk = { lo, hi (numeric id range | nil), names (blob), recs (blob | nil) }
local chunks = {}
local indexes = {} -- kind -> search blob
local cache = {} -- group -> { [id] = record | false } (weak values)
local roleCache = {} -- role -> { npcId, ... }
local meta
local announced = false
local WEAK = { __mode = "v" }

-- Blob lines: "\n" .. id .. "\t" .. flags .. "\t" .. name, and "\n" .. id .. "\t" .. record;
-- neither ids nor fields hold "\n" or "\t".
local NAME_LINE = "\n([^\t\n]*)\t([^\t\n]*)\t([^\n]*)"

local function key(s)
	return tonumber(s) or s
end

local function covers(c, id)
	local lo = c.lo
	if lo == nil then return true end
	return type(id) == "number" and id >= lo and id <= c.hi
end

-- blob, id -> offset of the field after "\n<id>\t" | nil
local function fieldAt(blob, id)
	local _, e = find(blob, "\n" .. id .. "\t", 1, true)
	return e and e + 1
end

-- blob, offset -> the rest of that line
local function lineFrom(blob, at)
	local stop = find(blob, "\n", at, true)
	return sub(blob, at, (stop or #blob + 1) - 1)
end

local function nameIn(c, id)
	local at = fieldAt(c.names, id)
	if not at then return nil end
	local tab = find(c.names, "\t", at, true)
	return lineFrom(c.names, tab + 1)
end

local function recordIn(c, id)
	local recs = c.recs
	local at = recs and fieldAt(recs, id)
	return at and lineFrom(recs, at)
end

-- group, id -> name, record string | nil (nil, nil when absent)
local function entryOf(group, id)
	local list = chunks[group]
	if not list or id == nil then return nil end
	for i = 1, #list do
		local c = list[i]
		if covers(c, id) then
			local name = nameIn(c, id)
			if name then return name, c end
		end
	end
	return nil
end

local function nameOf(group, id)
	return (entryOf(group, id))
end

local ITEM_GROUPS = { "item", "mount", "pet", "recipe", "tabard" }
local IS_ITEM = { item = true, mount = true, pet = true, recipe = true, tabard = true }
local NPC_GROUPS = { "npc", "rare" }
local OBJECT_GROUPS = { "object", "treasure" }
local SPAN = { item = ITEM_GROUPS, npc = NPC_GROUPS, object = OBJECT_GROUPS }

-- Same letters as FROM in tools/lib/codex/pack.js.
local FROM = {
	a = "atlasloot", c = "client", d = "dungeons", f = "flbis", j = "journal", l = "recordings",
	p = "pfquest", q = "questie", r = "rarescanner", w = "wowhead", e = "forever",
}

-- letter -> { type, fields }; same layout as SOURCE in pack.js.
local SOURCE = {
	v = { "vendor", { "npc", "cost", "limited" } },
	d = { "drop", { "npc", "chance", "instance" } },
	o = { "object", { "object", "chance" } },
	q = { "quest", { "quest", "choice" } },
	c = { "craft", { "spell", "skillLine", "skill" } },
	r = { "rep", { "faction", "standing", "npc" } },
	p = { "pvp", { "rank", "npc" } },
	n = { "container", { "item", "chance" } },
	w = { "world", { "minLevel", "maxLevel" } },
}
local BOOL_FIELD = { limited = true, choice = true }
local STRING_FIELD = { instance = true }

local OBJECTIVE = { k = "kill", i = "item", o = "object", e = "event" }

---------------------------------------------------------------------------
-- Decoding helpers
---------------------------------------------------------------------------

local PATTERN = { [";"] = "([^;]*);", [","] = "([^,]*)," }

-- s split by sep, empty fields kept -> list, n
local function split(s, sep)
	local t, n = {}, 0
	for f in gmatch(s .. sep, PATTERN[sep]) do
		n = n + 1
		t[n] = f
	end
	return t, n
end

local function hex(h) return char(tonumber(h, 16)) end

local function unesc(s)
	if s == nil or s == "" then return nil end
	if find(s, "%", 1, true) then s = gsub(s, "%%(%x%x)", hex) end
	return s
end

local function numbers(s)
	local out = {}
	if s == nil or s == "" then return out end
	local t, n = split(s, ",")
	for i = 1, n do out[i] = tonumber(t[i]) end
	return out
end

local function provenance(s)
	local out = {}
	for i = 1, #s do
		local name = FROM[sub(s, i, i)]
		if name then out[#out + 1] = name end
	end
	return out
end

local function decodeSource(field)
	local def = SOURCE[sub(field, 1, 1)]
	if not def then return nil end
	local parts = split(sub(field, 2), ",")
	local fields = def[2]
	local src = { type = def[1] }
	for i = 1, #fields do
		local key, v = fields[i], parts[i]
		if v and v ~= "" then
			if BOOL_FIELD[key] then src[key] = v == "1"
			elseif STRING_FIELD[key] then src[key] = unesc(v)
			else src[key] = tonumber(v) end
		end
	end
	src.from = provenance(parts[#fields + 1] or "")
	if src.type == "craft" and src.skillLine then
		src.profession = nameOf("skill", src.skillLine)
	end
	return src
end

-- "map,f,x,y,x,y" groups (fields first..n of t) -> flat { { map, x, y, f } }
local function decodeSpawns(t, first, n)
	local out = {}
	for i = first, n do
		local g, m = split(t[i], ",")
		local map, f = tonumber(g[1]), g[2] ~= "" and g[2] or nil
		for k = 3, m - 1, 2 do
			out[#out + 1] = { map = map, x = tonumber(g[k]) / 10, y = tonumber(g[k + 1]) / 10, f = f }
		end
	end
	return out
end

---------------------------------------------------------------------------
-- Record decoders: (group, id, string) -> record
---------------------------------------------------------------------------

local STATUS = { r = "retired", n = "nosource" }

local function decodeItem(group, id, s)
	local t, n = split(s, ";")
	local q, st = (t[1] or ""):match("^(%d*)(%a?)$")
	local rec = {
		id = id, name = nameOf(group, id), kind = group,
		quality = tonumber(q), reqLevel = tonumber(t[2]), spell = tonumber(t[3]),
		repFaction = tonumber(t[4]), repStanding = tonumber(t[5]), -- standing 1..8 (Hated..Exalted)
		reqSkill = tonumber(t[6]), reqSkillRank = tonumber(t[7]), -- skillLine, rank
		status = STATUS[st], -- "retired" (no longer obtainable) | "nosource" | nil
		sources = {},
	}
	for i = 8, n do
		local src = decodeSource(t[i])
		if src then rec.sources[#rec.sources + 1] = src end
	end
	return rec
end

local function decodeNpc(group, id, s)
	local t, n = split(s, ";")
	local flags = t[4] or ""
	local roles = {}
	if t[6] and t[6] ~= "" then
		local r, m = split(t[6], ",")
		for i = 1, m do roles[i] = unesc(r[i]) end
	end
	return {
		id = id, name = nameOf(group, id),
		level = tonumber(t[1]), levelMax = tonumber(t[2]),
		faction = t[3] ~= "" and t[3] or nil,
		rare = find(flags, "r", 1, true) ~= nil,
		elite = find(flags, "e", 1, true) ~= nil,
		boss = find(flags, "b", 1, true) ~= nil,
		instance = unesc(t[5]),
		roles = roles,
		loot = numbers(t[7]),
		spawns = decodeSpawns(t, 8, n),
	}
end

local function decodeObject(group, id, s)
	local t, n = split(s, ";")
	return { id = id, name = nameOf(group, id), treasure = t[1] == "1", loot = numbers(t[2]), spawns = decodeSpawns(t, 3, n) }
end

local function decodeQuest(group, id, s)
	local t, n = split(s, ";")
	local rec = {
		id = id, title = nameOf(group, id),
		level = tonumber(t[1]), minLevel = tonumber(t[2]),
		faction = t[3] ~= "" and t[3] or nil,
		races = tonumber(t[4]), classes = tonumber(t[5]), zone = tonumber(t[6]),
		start = { npc = numbers(t[7]), object = numbers(t[8]), item = numbers(t[9]) },
		["end"] = { npc = numbers(t[10]), object = numbers(t[11]) },
		pre = numbers(t[12]), rewards = numbers(t[13]), choices = numbers(t[14]), preAny = numbers(t[15]),
		objectives = {},
	}
	for i = 16, n do
		local f = t[i]
		local kind = OBJECTIVE[sub(f, 1, 1)]
		if kind then
			local _, _, oid, count, text = find(f, "^.([^,]*),([^,]*),(.*)$")
			rec.objectives[#rec.objectives + 1] = { type = kind, id = tonumber(oid), count = tonumber(count), text = unesc(text) }
		end
	end
	return rec
end

local function decodeInstance(group, id, s)
	local t, n = split(s, ";")
	local rec = {
		key = id, name = nameOf(group, id),
		kind = unesc(t[1]), forever = t[2] == "1",
		areaId = tonumber(t[3]), map = tonumber(t[4]),
		bosses = {},
	}
	if t[5] and t[5] ~= "" then
		local e = split(t[5], ",")
		-- approx: the client's corpse point (where a ghost returns), not the way in.
		rec.entrance = { map = tonumber(e[1]), x = tonumber(e[2]) / 10, y = tonumber(e[3]) / 10, f = e[4] ~= "" and e[4] or nil, approx = e[5] == "a" or nil }
	end
	if t[6] and t[6] ~= "" then rec.levels = numbers(t[6]) end
	for i = 7, n do
		local b, m = split(t[i], ",")
		local items = {}
		for k = 3, m do items[#items + 1] = tonumber(b[k]) end
		rec.bosses[#rec.bosses + 1] = { name = unesc(b[1]), npc = tonumber(b[2]), items = items }
	end
	return rec
end

local function decodeFaction(group, id, s)
	return { id = id, name = nameOf(group, id), side = unesc(s) }
end

local function decodeSpell(group, id, s)
	local t = split(s, ";")
	return { id = id, name = nameOf(group, id), kind = unesc(t[1]), item = tonumber(t[2]), class = unesc(t[3]) }
end

local DECODE = {
	item = decodeItem, mount = decodeItem, pet = decodeItem, recipe = decodeItem, tabard = decodeItem,
	npc = decodeNpc, rare = decodeNpc,
	object = decodeObject, treasure = decodeObject,
	quest = decodeQuest, instance = decodeInstance, faction = decodeFaction, spell = decodeSpell,
}

---------------------------------------------------------------------------
-- Registration and loading
---------------------------------------------------------------------------

function Codex.Register(group, names, recs, lo, hi)
	if group == "meta" then
		if type(names) == "table" then meta = names end
		return
	end
	if type(group) ~= "string" or type(names) ~= "string" then return end
	local list = chunks[group]
	if not list then
		list = {}
		chunks[group] = list
	end
	list[#list + 1] = {
		names = names,
		recs = type(recs) == "string" and recs or nil,
		lo = type(lo) == "number" and type(hi) == "number" and lo or nil,
		hi = type(lo) == "number" and type(hi) == "number" and hi or nil,
	}
	cache[group] = nil
	if group == "role" then roleCache = {} end
end

function Codex.RegisterIndex(kind, blob)
	if type(kind) == "string" and type(blob) == "string" then indexes[kind] = blob end
end

function Codex.Index(kind)
	return indexes[kind]
end

function Codex.IsLoaded()
	return meta ~= nil
end

function Codex.Meta()
	return meta
end

function Codex.Load()
	if not meta then
		local Data = ns.Data
		if not (Data and Data.Pack) then return false, "unavailable" end
		local loaded, reason = Data.Pack(PACK)
		if not meta then
			if loaded then return false, "empty" end
			return false, reason
		end
	end
	if not announced then
		announced = true
		if ns.Fire then ns.Fire("CODEX_LOADED", meta) end
	end
	return true
end

local function ready()
	if meta then return true end
	return (Codex.Load())
end

-- group, id -> record | nil (decoded once)
local function get(group, id)
	local c = cache[group]
	if c then
		local rec = c[id]
		if rec ~= nil then return rec or nil end
	end
	local name, chunk = entryOf(group, id)
	if name == nil then return nil end
	local s = recordIn(chunk, id)
	local rec
	if s and DECODE[group] then rec = DECODE[group](group, id, s) end
	if not rec then rec = { id = id, name = name } end
	if not c then
		-- Weak values: records nobody holds are decoded again on demand.
		c = setmetatable({}, WEAK)
		cache[group] = c
	end
	c[id] = rec
	return rec
end

local function first(groups, id)
	for i = 1, #groups do
		local rec = get(groups[i], id)
		if rec then return rec end
	end
	return nil
end

function Codex.Item(id)
	id = tonumber(id)
	if not (id and ready()) then return nil end
	return first(ITEM_GROUPS, id)
end

function Codex.Npc(id)
	id = tonumber(id)
	if not (id and ready()) then return nil end
	return first(NPC_GROUPS, id)
end

function Codex.Object(id)
	id = tonumber(id)
	if not (id and ready()) then return nil end
	return first(OBJECT_GROUPS, id)
end

function Codex.Quest(id)
	id = tonumber(id)
	if not (id and ready()) then return nil end
	return get("quest", id)
end

function Codex.Instance(key)
	if key == nil or not ready() then return nil end
	return get("instance", key)
end

function Codex.Zone(id)
	id = tonumber(id)
	if not (id and ready()) then return nil end
	return get("zone", id)
end

function Codex.Faction(id)
	id = tonumber(id)
	if not (id and ready()) then return nil end
	return get("faction", id)
end

function Codex.Spell(id)
	id = tonumber(id)
	if not (id and ready()) then return nil end
	return get("spell", id)
end

function Codex.Name(kind, id)
	if id == nil or not ready() then return nil end
	if kind ~= "instance" then id = tonumber(id) or id end
	local groups = SPAN[kind]
	if groups then
		for i = 1, #groups do
			local name = nameOf(groups[i], id)
			if name then return name end
		end
		return nil
	end
	return nameOf(kind, id)
end

local EMPTY = {}
local LOOT_GROUPS = { rare = { "rare" }, npc = NPC_GROUPS, treasure = { "treasure" }, object = OBJECT_GROUPS }

function Codex.Loot(kind, id)
	local groups = LOOT_GROUPS[kind]
	id = tonumber(id)
	if not (groups and id and ready()) then return EMPTY end
	local rec = first(groups, id)
	return rec and rec.loot or EMPTY
end

function Codex.WithRole(role)
	if role == nil or not ready() then return {} end
	local hit = roleCache[role]
	if hit then return hit end
	hit = numbers(nameOf("role", role))
	roleCache[role] = hit
	return hit
end

-- flags ("" or quality digit, then status letter) -> quality, status
local function itemFlags(flags)
	local b, c = byte(flags, 1, 2)
	local quality
	if b and b >= 48 and b <= 57 then quality = b - 48 else c = b end
	if c == 114 then return quality, "retired" end
	if c == 110 then return quality, "nosource" end
	return quality
end

function Codex.Each(kind, fn)
	if not ready() then return end
	local list = chunks[kind]
	if not list then return end
	local isItem = IS_ITEM[kind]
	for i = 1, #list do
		for k, flags, name in gmatch(list[i].names, NAME_LINE) do
			local quality, status
			if isItem then quality, status = itemFlags(flags) end
			if fn(key(k), name, quality, status) == false then return end
		end
	end
end
